import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int A = sc.nextInt();
        int B = sc.nextInt();
        sc.close();

        // Ana: começa na cadeira 1 e conta A cadeiras -> cadeira = A % 3
        int a = A % 3;

        // Beatriz: começa na cadeira 1 e conta B cadeiras -> cadeira = B % 3
        int b = B % 3;

        // Se a cadeira de Beatriz coincide com a de Ana, ela senta na próxima (anti-horário)
        if (b == a) {
            b = (b + 1) % 3;
        }

        // Carolina senta na cadeira restante (as três cadeiras 0,1,2 somam 3)
        int carolina = 3 - a - b;

        System.out.println(carolina);
    }
}
